	authority    SupervisorIntentAuthority
	installation RepositoryWorktreeInstallationAuthority
	observation  RepositoryWorktreeMaterializationObservation
	canonical    []byte
	snapshot     *VerifiedRepositoryWorktreeSnapshot
	now          time.Time
