	case RepositoryWorktreeNewExact:
		if action != RepositoryWorktreeAdmitNew || !snapshot.unambiguous || !snapshot.tupleUnique || !snapshot.slotUnique ||
			!snapshot.ownershipCertain || !exactRepositoryWorktreeClosure(observation, installation, authorization.authorization.Scope.WritablePaths, true) {
