			!snapshot.ownershipCertain || !exactRepositoryWorktreeClosure(observation, installation, authorization.authorization.Scope.WritablePaths, false) {
			return invalid, nil, ErrInvalidRepositoryWorktree
		}
		return RepositoryWorktreeAssessment{
			Disposition:     RepositoryWorktreeRetainedStatus,
